INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter booleschen Literalen?', 2, '[{"text": "Logische Werte true und false", "correct": true, "because": "Wahrheitswerte"}, {"text": "Zahlenwerte", "correct": false, "because": "Numerische Literale"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit booleschen Literalen?', 3, '[{"text": "Logische Bedingungen darstellen", "correct": true, "because": "Entscheidungen treffen"}, {"text": "Speicherplatz sparen", "correct": false, "because": "Indirekt"}, {"text": "Design verbessern", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werte haben boolesche Literale?', 5, '[{"text": "true", "correct": true, "because": "Wahr"}, {"text": "false", "correct": true, "because": "Falsch"}, {"text": "1", "correct": false, "because": "Numerisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Boolesche Literale haben zwei Werte. b) Sie sind nur in SQL nutzbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch andere Sprachen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei booleschen Literalen?', 4, '[{"text": "Logische Bedeutung", "correct": false, "because": "Kern der Literale"}, {"text": "Verwendung in Bedingungen", "correct": false, "because": "Hauptanwendung"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob true in SQL als 1 dargestellt wird?', 2, '[{"text": "Ja", "correct": true, "because": "Interne Darstellung"}, {"text": "Nein", "correct": false, "because": "Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche SQL-Abfrage nutzt ein boolesches Literal?', 3, '[{"text": "SELECT * FROM users WHERE active = true", "correct": true, "because": "Logische Bedingung"}, {"text": "INSERT INTO users VALUES (1)", "correct": false, "because": "Kein Literal"}, {"text": "DELETE FROM users", "correct": false, "because": "Kein Literal"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Arbeit mit booleschen Literalen?', 5, '[{"text": "Logische Operatoren", "correct": true, "because": "AND, OR"}, {"text": "Bedingungen", "correct": true, "because": "If, Where"}, {"text": "Farbcodierung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Boolesche Literale werden in Bedingungen genutzt. b) Sie sind nur für Zahlenoperationen geeignet. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Logische Operationen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei booleschen Literalen unwichtig?', 4, '[{"text": "Wahrheitswert", "correct": false, "because": "Kern"}, {"text": "Logische Verknüpfung", "correct": false, "because": "Anwendung"}, {"text": "Schriftart", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein boolesches Literal in SQL mehrere Werte haben?', 2, '[{"text": "Nein", "correct": true, "because": "Nur true/false"}, {"text": "Ja", "correct": false, "because": "Binär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten boolesche Literale?', 4, '[{"text": "Klarheit in Logik", "correct": true, "because": "Einfache Bedingungen"}, {"text": "Effiziente Entscheidungen", "correct": true, "because": "Programmsteuerung"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass boolesche Literale nur in Hochsprachen genutzt werden. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Assembler"}, {"text": "Ja", "correct": false, "because": "Universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei booleschen Literalen?', 3, '[{"text": "Logische Korrektheit", "correct": true, "because": "Funktion"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Boolesche Literale können mit AND verknüpft werden. b) Sie sind nur für Datenbanken nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Programmierung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine falsche Verwendung von booleschen Literalen?', 5, '[{"text": "Logikfehler", "correct": true, "because": "Falsche Bedingungen"}, {"text": "Programmabsturz", "correct": true, "because": "Fehlerhafte Steuerung"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker bei booleschen Literalen?', 3, '[{"text": "Logische Bedingungen implementieren", "correct": true, "because": "Programmierung"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein boolesches Literal in einer Datenbank gespeichert werden?', 2, '[{"text": "Ja", "correct": true, "because": "z.B. BOOLEAN"}, {"text": "Nein", "correct": false, "because": "Unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche SQL-Bedingung nutzt boolesche Literale?', 4, '[{"text": "WHERE is_active = true", "correct": true, "because": "Logische Abfrage"}, {"text": "INSERT INTO table (1)", "correct": false, "because": "Kein Literal"}, {"text": "SELECT * FROM table", "correct": false, "because": "Keine Bedingung"}]');
